<?php $popup=null;foreach(($portalAnnouncements??[])as$a){if(!empty($a['show_popup'])){$popup=$a;break;}}if($popup):?>
<div class="announcement-modal" data-announcement-popup="<?=$popup['id']?>" hidden><div class="announcement-modal__backdrop" data-announcement-close></div><section class="announcement-modal__card" role="dialog" aria-modal="true" aria-labelledby="announcementTitle"><button class="announcement-modal__close" type="button" data-announcement-close aria-label="Close">&times;</button><?php if($popup['image_path']):?><img src="<?=url('/attachments/announcements/'.$popup['id'])?>" alt=""><?php endif?><span class="module-eyebrow"><?=!empty($popup['teacher_id'])?'Announcement from '.e($popup['teacher_name']??'your teacher'):'Announcement'?></span><h2 id="announcementTitle"><?=e($popup['title'])?></h2><p><?=nl2br(e($popup['message']))?></p><a class="btn btn--primary" href="<?=url('/portal/announcements')?>">View all announcements</a></section></div>
<script>document.addEventListener('DOMContentLoaded',()=>{const m=document.querySelector('[data-announcement-popup]');if(!m)return;const k='announcement-dismissed-'+m.dataset.announcementPopup;if(!sessionStorage.getItem(k))m.hidden=false;m.querySelectorAll('[data-announcement-close]').forEach(x=>x.addEventListener('click',()=>{m.hidden=true;sessionStorage.setItem(k,'1')}))});</script>
<?php endif?>
